"""Complete the static route inventory; invoked by build.py in its template context."""
import sys
sys.path.insert(0,str(ROOT/'content'))
from products import PRODUCTS
import importlib.util
spec=importlib.util.spec_from_file_location('packhub_collections',ROOT/'content/collections.py')
collection=importlib.util.module_from_spec(spec);spec.loader.exec_module(collection)
INDUSTRIES=collection.INDUSTRIES;MATERIALS=collection.MATERIALS;SERVICES=collection.SERVICES;EXTRA_GUIDES=collection.EXTRA_GUIDES

def related(items):
 return '<div class="formats">'+''.join('<a class="format related-card" href="/products/'+p+'/"><span class="eyebrow">Related packaging</span><h3>'+esc(next(row[1] for row in PRODUCTS[p.split('/')[0]] if row[0]==p.split('/')[1]))+'</h3><span class="textlink">Explore specifications ↗</span></a>' for p in items)+'</div>'

def scene(name,alt):
 file={'coffee':'print-coffee','beauty':'print-beauty','packing':'print-packing','general':'print-collection'}[name]
 return '<figure class="scene"><img src="/assets/images/'+file+'.webp" alt="'+esc(alt,quote=True)+'" width="1536" height="1024" loading="lazy"><figcaption>Original fictional-brand design reference.</figcaption></figure>'

def sections(items):return ''.join('<section><h2>'+esc(title)+'</h2><p>'+esc(text)+'</p></section>' for title,text in items)

for c in CATEGORIES:
 family=c['slug'];items=PRODUCTS[family]
 body=intro(c['name'],c['name']+' for a complete brand experience.',c['intro'],'<a href="/products/">Packaging</a> / '+c['name'])
 body+='<section class="wrap categorylead"><div><h2>Choose your structure.<br>Make the print yours.</h2><p style="margin-top:22px">'+c['summary']+'</p><div class="actions" style="margin-top:25px">'+button('Discuss my packaging',qurl(c['name']))+'</div></div>'+art(c['art'])+'</section>'
 body+='<section class="section wrap"><span class="eyebrow">COMPARE THE FORMATS</span><h2>Find the right starting point.</h2><div class="formats" style="margin-top:28px">'
 for slug,name,desc,options,check,use in items:body+='<article class="format"><h3>'+name+'</h3><p>'+desc+'</p><a class="textlink" href="/products/'+family+'/'+slug+'/">Explore '+name.lower()+' ↗</a></article>'
 body+='</div></section><section class="section mutedbg"><div class="wrap"><h2>Build a specification you can compare.</h2>'+table([('Contents & channel','Product dimensions or fill weight, packed load, intended use and sales channel.'),('Quantity & versions','Quantity per size and design, artwork variations and expected reorder pattern.'),('Print & appearance','Logo, slogan, artwork, printed sides, color priorities and finish references.'),('Sample & approval','The fit, print, handling or functional decision the sample needs to answer.'),('Destination & timing','Country or region, target arrival window and preferred shipment basis.')])+'</div></section><section class="section wrap faqwrap"><h2>Plan before<br>you print.</h2>'+faq()+'</section>'+cta()
 write('/products/'+family+'/',c['name']+' with Custom Printing | PackHubGlobe',c['summary'],body)
 for slug,name,desc,options,check,use in items:
  path='/products/'+family+'/'+slug+'/'
  title='Custom '+name.lower()+' with Logo Printing'
  title=title[0].upper()+title[1:]
  body=intro(c['name'],title,desc,'<a href="/products/">Packaging</a> / <a href="/products/'+family+'/">'+c['name']+'</a> / '+name)
  body+='<section class="wrap categorylead"><div>'+art(c['art'])+'<p class="smallnote">Packaging family design reference. Final structure is specified for your product.</p></div><div><span class="eyebrow">APPLICATION &amp; STRUCTURE</span><h2>A useful format.<br>Your own identity.</h2><p style="margin-top:22px">'+use+'</p><div class="inlinefacts"><span>Custom artwork</span><span>Size &amp; material review</span><span>Project-based MOQ</span></div><div class="actions" style="margin-top:25px">'+button('Request '+name.lower(),qurl(name))+'</div></div></section>'
  body+='<section class="section wrap"><div class="sectionhead"><div><span class="eyebrow">SPECIFY THE DETAILS</span><h2>What should your brief include?</h2></div></div>'+table([('Structure & options',options),('Product & fit','Share the actual contents, dimensions or fill weight, plus packing orientation and clearances.'),('Artwork & print','Provide logo and slogan artwork, color references, printed faces and finish priorities.'),('Quantity & variants','State the quantity for each size and design so setup and production can be reviewed accurately.'),('Sample review',check),('Delivery','Include destination, target timing and how the finished packaging will be stored and handled.')])+'</section>'
  body+='<section class="section mutedbg"><div class="wrap two"><article class="panel"><h3>Approve the function.</h3><p>'+check+'</p><p>Agree the sample type and any test method before approval. Record the structure, material and artwork revision that the sample represents.</p></article><article class="panel"><h3>Make the design work in print.</h3><p>Use your own logo, color system, slogan and graphics. Review small text, print coverage and graphic placement against the actual folds, seals or attachment areas.</p><p>Requested finishes and features are reviewed against the chosen material and print route. A visual reference does not establish final production performance.</p></article></div></section>'
  other=[family+'/'+r[0] for r in items if r[0]!=slug][:3]
  body+='<section class="section wrap"><div class="sectionhead"><div><span class="eyebrow">CONTINUE THE BRIEF</span><h2>Compare related formats.</h2></div><a class="textlink" href="/guides/packaging-quote-checklist/">Prepare your quote details ↗</a></div>'+related(other)+'</section>'+cta()
  write(path,title+' | PackHubGlobe',desc,body,[{'@type':'Service','name':title,'description':desc,'serviceType':'Packaging specification and custom printing'}])

overview=intro('Industry solutions','One packaging partner.<br>Different brand worlds.','Find an application that matches your product. Connect the structure, graphic identity and packing requirements across boxes, bags, pouches and printed details.')+'<section class="wrap section" style="padding-top:0"><div class="industry-grid">'
for slug,name,desc,brief,approach,check,links,img in INDUSTRIES:
 overview+='<a class="industry-card" href="/industries/'+slug+'/">'+scene(img,name+' with original printed brand concepts')+'<div class="cardtitle"><h3>'+name+'</h3><span class="arrow" aria-hidden="true">↗</span></div><p>'+desc+'</p></a>'
 body=intro('Industry packaging',name,desc,'<a href="/industries/">Industries</a> / '+name)
 body+='<section class="wrap split">'+scene(img,'Illustrative '+name.lower()+' including branded printed components')+'<div><span class="eyebrow">A BRIEF BUILT AROUND YOUR PRODUCT</span><h2>Function first.<br>Brand in every detail.</h2><p>'+brief+'</p><div class="actions" style="margin-top:25px">'+button('Plan this packaging range',qurl(name))+'</div></div></section>'
 body+='<section class="section wrap"><div class="two"><article class="panel"><h3>Choose the packaging system.</h3><p>'+approach+'</p></article><article class="panel"><h3>Review the risks that matter.</h3><p>'+check+'</p></article></div></section><section class="section mutedbg"><div class="wrap"><div class="sectionhead"><div><span class="eyebrow">A CONNECTED RANGE</span><h2>Explore the packaging components.</h2></div></div>'+related(links)+'</div></section><section class="section wrap"><h2>Get a comparable quotation.</h2>'+table([('Product details',brief),('Primary & outer packaging','Identify direct-contact packaging, retail presentation, shipping protection and printed accessories separately.'),('Artwork & range','List designs, sizes, color references, product variants and quantity per component.'),('Sampling',check),('Destination & timing','State the destination market and target arrival window, including any required material documents.')])+'</section>'+cta()
 write('/industries/'+slug+'/',name+' Solutions | PackHubGlobe',desc,body)
overview+='</div></section>'+cta()
write('/industries/','Custom Packaging by Industry | PackHubGlobe','Explore custom packaging for beauty, coffee, food, pet products, apparel, gifting, ecommerce and more.',overview)

for root,label,records in [('materials','Materials & finishes',MATERIALS),('services','Packaging services',SERVICES)]:
 overview=intro(label,'Better decisions.<br>From material to final pack.','Use these practical guides to define your packaging brief, review options and agree the specification and approvals needed for your project.')+'<section class="section wrap" style="padding-top:0"><div class="formats">'
 for slug,name,desc,first,second,third,links in records:
  overview+='<article class="format"><span class="eyebrow">'+label+'</span><h3>'+name+'</h3><p>'+desc+'</p><a class="textlink" href="/'+root+'/'+slug+'/">Explore the details ↗</a></article>'
  body=intro(label,name,desc,'<a href="/'+root+'/">'+label+'</a> / '+name)
  body+='<article class="article wrap">'+sections([('Start with the requirement',first),('Connect the material and the process',second),('Agree the evidence and approval',third)])+'<h2>Prepare a useful project brief.</h2><p>Include the product, packaging format, approximate size or fill weight, quantity per design, artwork and destination. Mark requirements that are fixed and decisions that need review.</p><p>Request a clear quotation covering the selected specification, sample route, production basis and shipping assumptions. <a href="/request-quote/">Prepare your packaging brief</a>.</p></article><section class="section mutedbg"><div class="wrap"><div class="sectionhead"><h2>Put the decision into practice.</h2></div>'+related(links)+'</div></section>'+cta()
  write('/'+root+'/'+slug+'/',name+' | PackHubGlobe',desc,body)
 overview+='</div></section>'+cta()
 write('/'+root+'/',label+' | PackHubGlobe','Explore '+label.lower()+' for custom boxes, bags, pouches, cards and labels.',overview)

allguides=[(g[0],g[2],g[3],g[4]) for g in GUIDES]+EXTRA_GUIDES
overview=intro('The packaging notebook','Useful answers.<br>More confident packaging decisions.','Practical guidance for brand teams and buyers: compare structures, clarify dimensions, prepare artwork and choose the right sample.')+'<section class="section wrap" style="padding-top:0"><div class="resourcegrid">'
for slug,title,desc,chapters in allguides:
 overview+='<article class="guidecard"><span class="eyebrow">Buyer guide</span><h3><a href="/guides/'+slug+'/">'+title+'</a></h3><p>'+desc+'</p><a class="textlink" href="/guides/'+slug+'/">Read the guide ↗</a></article>'
 body=intro('Buyer guide',title,desc,'<a href="/guides/">Guides</a> / '+title)
 body+='<article class="article wrap"><p class="articlebyline">PackHubGlobe packaging notebook · General procurement guidance</p>'+sections(chapters)+'<h2>Bring the question into your project.</h2><p>General guidance does not replace a specification or test for your actual product. Bring your format, contents, quantity, artwork and destination into the discussion. <a href="/request-quote/">Prepare a packaging enquiry</a>, <a href="/services/sampling/">compare sample types</a> or <a href="/products/">explore the product formats</a>.</p><h2>Editorial scope</h2><p>This guide explains decisions to discuss with a packaging supplier. It does not claim a particular test result, certification or fixed production capability. Read our <a href="/editorial-policy/">editorial policy</a> for source and revision principles.</p></article>'+cta()
 write('/guides/'+slug+'/',title+' | PackHubGlobe',desc,body)
overview+='</div></section>'+cta()
write('/guides/','Packaging Guides for B2B Buyers | PackHubGlobe','Compare packaging structures, dimensions, print proofs, sample types, label rolls and material choices.',overview)

body=intro('Packaging projects','Different brands.<br>A complete packaging story.','Explore original fictional-brand concepts showing how boxes, bags, pouches, cards and labels can work together. These are design references, not customer testimonials or completed-order claims.')+'<section class="section wrap" style="padding-top:0">'
for name,desc,links,img in [('Coffee range','A pouch-led range with a retail bag, labels and a printed card. Review filling, seal clearance and aroma requirements before choosing the final material.',['flexible-pouches/flat-bottom-pouches','paper-bags/kraft-paper-bags','stickers-labels/roll-labels'],'coffee'),('Beauty presentation','A coordinated carton, fitted gift box, shopping bag and care card. Review the product dimensions and insert contact before approving decorative finishes.',['custom-boxes/rigid-boxes','custom-boxes/folding-cartons','cards-tags/care-cards'],'beauty'),('Ecommerce unboxing','A mailer, tissue and printed card can connect presentation with a repeatable packing workflow. Validate the complete parcel arrangement with the real contents.',['custom-boxes/mailer-boxes','cards-tags/insert-cards','stickers-labels/packaging-seals'],'packing')]:
 body+='<section class="project-example"><div class="split">'+scene(img,name+' fictional-brand packaging design reference')+'<div><span class="eyebrow">Original design concept</span><h2>'+name+'</h2><p>'+desc+'</p><div class="actions" style="margin-top:25px">'+button('Discuss a similar direction',qurl(name))+'</div></div></div><div style="margin-top:30px">'+related(links)+'</div></section>'
body+='</section>'+cta()
write('/cases/','Packaging Project & Print Design References | PackHubGlobe','Explore original packaging design concepts for coffee, beauty and ecommerce, with product specifications to discuss.',body)

privacy=[('Your enquiry','The packaging form prepares an email draft or a downloadable text brief in your browser. It does not automatically submit your details to a form server. Opening the draft passes the details to your chosen email application; sending that email delivers it to andrew@packhubglobe.com.'),('Information you choose to provide','An email enquiry may include your name, business email, company, product requirements and files you attach. Provide only information needed to discuss the packaging project. Avoid sending unnecessary personal or sensitive data.'),('Purpose and contact','We use enquiry information to discuss specifications, provide quotations, arrange samples and handle the requested business relationship. Email and hosting providers may process information as part of delivering those services. Hosting may also record ordinary technical access logs.'),('Your choices','You can contact andrew@packhubglobe.com to ask about your enquiry information or request correction or deletion, subject to any applicable record-keeping requirements. Form input is not intentionally saved to browser storage by this website.'),('Website resources','Images, fonts, styles and scripts are hosted with this website. No visitor analytics, advertising pixels or marketing-cookie system is installed in this version. External reference links have their own policies. The companies behind the brand are identified on the About page.')]
write('/privacy/','Privacy & Enquiry Information | PackHubGlobe','Read how PackHubGlobe handles email enquiries, form input and website resources.',intro('Privacy information','A clear starting point<br>for your enquiry.','Understand what this website does with the information you choose to share.')+'<article class="article wrap">'+sections(privacy)+'<p><a href="/about/">About PackHubGlobe</a> · <a href="mailto:'+EMAIL+'">Contact us about your information</a></p></article>')
terms=[('Information and quotations','This website introduces packaging formats and decisions to review. A product page or design reference is not a binding quotation. Price, minimum quantity, materials, features, samples, production, payment and delivery are confirmed in the written quotation and agreed order.'),('Specifications and artwork','Confirm dimensions, material, print, finish, quantity and artwork versions before production. The customer should approve product wording, claims, translations, barcodes and other content, and have the right to use any supplied artwork.'),('Samples and timing','Samples answer the decisions agreed for their sample type. A sample or illustration does not establish every aspect of final performance. Production and shipping dates require project-specific confirmation; delivery assumptions should be clear in the quotation.'),('Design references','Original virtual-brand images on this website illustrate printing and packaging directions. They do not represent endorsements, registered customer brands, test results or completed client orders. Requested finishes and features are subject to material and production review.'),('Responsible supply','The written quotation identifies the supplying company and the agreed commercial terms. Read About and Factory for the companies and areas of responsibility behind PackHubGlobe. Contact andrew@packhubglobe.com for a project-specific clarification.')]
write('/terms/','Quotation & Website Information | PackHubGlobe','Understand how packaging references, quotations, artwork, samples and order specifications are handled.',intro('Quotation information','Clear details.<br>A better project brief.','The points below explain how website information relates to a packaging enquiry and an agreed order.')+'<article class="article wrap">'+sections(terms)+'<p><a href="/about/">About the brand</a> · <a href="/request-quote/">Prepare your enquiry</a></p></article>')
editorial=[('Purpose','The packaging notebook helps buyers ask clearer questions and prepare comparable specifications. Product, material and process guidance is framed around the actual application rather than a universal promise.'),('Claims and evidence','We do not publish invented prices, delivery guarantees, ratings, test results or certifications. Numerical performance and compliance claims need evidence for the relevant material, structure, intended use and conditions.'),('Imagery','Original fictional logos, slogans and photorealistic design references demonstrate graphic directions. They are labelled as concepts and are not used as proof of a factory, certificate or customer relationship.'),('Sources and revisions','Company information is linked to source profiles on the About and Factory pages. Guidance should be revised when a relevant specification or source changes. We do not change dates solely to imply freshness.'),('Corrections','Email andrew@packhubglobe.com with the page URL and the point that needs review. For a purchasing decision, request a written specification and suitable sample or evidence for your actual project.')]
write('/editorial-policy/','Editorial & Image Policy | PackHubGlobe','Read PackHubGlobe’s approach to procurement guidance, factual claims, original concept imagery and corrections.',intro('Editorial policy','Useful information.<br>Clear boundaries.','How we present packaging guidance, design references and project information.')+'<article class="article wrap">'+sections(editorial)+'</article>')

